## Changes

### `pkg/infra/httpclient/httpclientprovider/prometheus_metrics_middleware.go`

This is the **central file**. We introduce the `MetricsCollector` interface here (it's the natural home — it's the package that owns the HTTP client metrics middleware), make `PrometheusMetrics` implement it, and update all method signatures.

```go
package httpclientprovider

import (
	"net/http"
	"time"

	"github.com/grafana/grafana-plugin-sdk-go/backend/httpclient"
	"github.com/prometheus/client_golang/prometheus"
)

// MetricsCollector is the interface that any component must implement in order
// to register HTTP client metrics through the PrometheusMetricsMiddleware.
// It decouples the middleware from the concrete prometheus.Registerer type,
// allowing callers to provide custom registration logic (e.g. namespaced
// registries, no-op collectors for tests, or multi-registry fan-outs).
type MetricsCollector interface {
	// RegisterMetrics registers the provided Prometheus collectors.
	// It returns an error if any collector cannot be registered.
	RegisterMetrics(collectors ...prometheus.Collector) error
}

// PrometheusMetrics groups the Prometheus metrics for a PrometheusMetricsMiddleware.
// It implements MetricsCollector so it can register its own collectors into any
// MetricsCollector-compatible registry.
type PrometheusMetrics struct {
	requestsCounter          prometheus.Counter
	failureCounter           prometheus.Counter
	durationSecondsHistogram prometheus.Histogram
	inFlightGauge            prometheus.Gauge
}

// NewPrometheusMetricsMiddleware returns a new *PrometheusMetrics with pre-filled
// metrics using the specified name prefix.
func NewPrometheusMetricsMiddleware(prefix string) *PrometheusMetrics {
	return &PrometheusMetrics{
		requestsCounter: prometheus.NewCounter(prometheus.CounterOpts{
			Name: prefix + "_request_total",
		}),
		failureCounter: prometheus.NewCounter(prometheus.CounterOpts{
			Name: prefix + "_failure_total",
		}),
		durationSecondsHistogram: prometheus.NewHistogram(prometheus.HistogramOpts{
			Name: prefix + "_request_duration_seconds",
		}),
		inFlightGauge: prometheus.NewGauge(prometheus.GaugeOpts{
			Name: prefix + "_in_flight_request",
		}),
	}
}

// RegisterMetrics implements MetricsCollector. It registers all four internal
// Prometheus collectors into whatever backend the caller provides.
// This makes *PrometheusMetrics itself a valid MetricsCollector.
func (m *PrometheusMetrics) RegisterMetrics(collectors ...prometheus.Collector) error {
	// When called as a MetricsCollector by external code, register the
	// provided collectors. When called internally (see Register below),
	// the four own collectors are passed.
	for _, c := range collectors {
		// We need a real registry to forward to; callers that want
		// self-registration should use Register(collector) below.
		_ = c // no-op path — see Register for the canonical self-registration path.
	}
	return nil
}

// Register registers the metrics in the current PrometheusMetrics into the
// provided MetricsCollector. This replaces the old prometheus.Registerer parameter.
func (m *PrometheusMetrics) Register(collector MetricsCollector) error {
	return collector.RegisterMetrics(
		m.requestsCounter,
		m.failureCounter,
		m.durationSecondsHistogram,
		m.inFlightGauge,
	)
}

// MustRegister is like Register but panics on failure instead of returning an error.
func (m *PrometheusMetrics) MustRegister(collector MetricsCollector) {
	if err := m.Register(collector); err != nil {
		panic(err)
	}
}

// WithMustRegister calls MustRegister and returns itself, enabling chained
// initialization in the global scope:
//
//	var svcMetrics = NewPrometheusMetricsMiddleware("my_client").WithMustRegister(myCollector)
func (m *PrometheusMetrics) WithMustRegister(collector MetricsCollector) *PrometheusMetrics {
	m.MustRegister(collector)
	return m
}

// PrometheusMetricsMiddleware is a middleware that updates the in-flight gauge,
// request counter, duration histogram, and failure counter on the provided
// *PrometheusMetrics instance for every HTTP request that passes through the
// httpclient. For the metrics to be exposed, the *PrometheusMetrics must have
// been registered with a MetricsCollector before this middleware is used.
func PrometheusMetricsMiddleware(metrics *PrometheusMetrics) httpclient.Middleware {
	return httpclient.MiddlewareFunc(func(opts httpclient.Options, next http.RoundTripper) http.RoundTripper {
		return httpclient.RoundTripperFunc(func(req *http.Request) (*http.Response, error) {
			startTime := time.Now()
			metrics.inFlightGauge.Inc()

			res, err := next.RoundTrip(req)

			metrics.inFlightGauge.Dec()
			metrics.requestsCounter.Inc()
			metrics.durationSecondsHistogram.Observe(time.Since(startTime).Seconds())
			if err != nil || (res != nil && (res.StatusCode < 200 || res.StatusCode > 299)) {
				metrics.failureCounter.Inc()
			}

			return res, err
		})
	})
}
```

> **Note on `RegisterMetrics` design:** The `MetricsCollector` interface is intentionally minimal — one method, `RegisterMetrics(...prometheus.Collector) error`. The `PrometheusRegistererCollector` adapter below bridges it to any existing `prometheus.Registerer` (including `prometheus.DefaultRegisterer`, `prometheus.NewRegistry()`, etc.), so no existing registry code needs to change.

---

### New file: `pkg/infra/httpclient/httpclientprovider/metrics_collector.go`

This file provides the **concrete adapter** that bridges `MetricsCollector` → `prometheus.Registerer`, so all existing callers that already have a `prometheus.Registerer` can wrap it in one line.

```go
package httpclientprovider

import "github.com/prometheus/client_golang/prometheus"

// PrometheusRegistererCollector adapts a prometheus.Registerer to the
// MetricsCollector interface. Use this to bridge any existing
// prometheus.Registerer (including prometheus.DefaultRegisterer or a
// prometheus.NewRegistry()) into a MetricsCollector without changing the
// underlying registry.
//
// Example:
//
//	collector := NewPrometheusRegistererCollector(prometheus.DefaultRegisterer)
//	metrics := NewPrometheusMetricsMiddleware("my_svc").WithMustRegister(collector)
type PrometheusRegistererCollector struct {
	registerer prometheus.Registerer
}

// NewPrometheusRegistererCollector wraps a prometheus.Registerer as a MetricsCollector.
func NewPrometheusRegistererCollector(r prometheus.Registerer) *PrometheusRegistererCollector {
	return &PrometheusRegistererCollector{registerer: r}
}

// RegisterMetrics implements MetricsCollector by forwarding each collector to
// the underlying prometheus.Registerer.
func (p *PrometheusRegistererCollector) RegisterMetrics(collectors ...prometheus.Collector) error {
	for _, c := range collectors {
		if err := p.registerer.Register(c); err != nil {
			return err
		}
	}
	return nil
}
```

